const incoming = $input.all();

let existingText = '';
try {
  existingText = $('Extract From File').first()?.json?.data || '';
} catch (e) {
  throw new Error(`Failed to read existing storage: ${e.message}`);
}

const existingUrls = new Set(
  existingText.split('\n').filter(Boolean).map(line => {
    try { return JSON.parse(line).source_url; } catch { return null; }
  }).filter(Boolean)
);

const PLACEHOLDER = 'Unclassified — pending AI extraction';

const normalized = incoming.map((item) => {
  const q = item.json;
  const questionId = q.question_id;
  const sourceUrl = q.link;
  const title = q.title || '(untitled)';
  const tags = Array.isArray(q.tags) ? q.tags.join(', ') : '';
  const rawText = tags ? `${title} — tags: ${tags}` : title;

  return {
    signal_id: `se-${questionId}`,
    source_type: 'public_api',
    source_name: 'Stack Exchange (Software Recommendations)',
    source_url: sourceUrl,
    signal_date: q.creation_date ? new Date(q.creation_date * 1000).toISOString() : null,
    market: PLACEHOLDER,
    opportunity_category: PLACEHOLDER,
    opportunity_title: title,
    problem: rawText,
    target_customer: PLACEHOLDER,
    demand_signal: rawText,
    proposed_solution: PLACEHOLDER,
    monetization_model: PLACEHOLDER,
    delivery_method: PLACEHOLDER,
    geography: PLACEHOLDER,
    evidence_notes: `Raw signal ingested from Stack Exchange (Software Recommendations) via api.stackexchange.com v2.3. Question ID ${questionId}, score ${q.score ?? 0}, ${q.answer_count ?? 0} answers, ${q.view_count ?? 0} views. Not yet human-reviewed.`,
    _dedupe_url: sourceUrl
  };
});

const fresh = normalized.filter((rec) => !existingUrls.has(rec._dedupe_url));

return fresh.map((rec) => {
  const { _dedupe_url, ...clean } = rec;
  return { json: clean };
});
